// --- Galestream Insight (usa6qyq3ka): "Look at the top six cards of your deck. You may reveal a Spell card from
// among them and put it into your memory. Put the rest on the bottom of your deck in any order." ---
// Pre-fix engine bug: GalestreamInsightResolve() pulled the six cards with a loop of MZMove($player, "myDeck-0",
// "myTempZone"). Remove() only flags the slot removed (no splice), so every iteration after the first resolved
// "myDeck-0" to the same already-removed slot and MZMove's own "already removed" guard silently no-oped: only the
// top card was ever looked at, and the spells deeper in the top six were never offered.
$gaGalestreamDeck = <<<'DECK'
# Material
1 Spirit of Wind
# Main
10 Dungeon Guide
10 Fluffy Shopkeep
DECK;
$gaGalestreamSetup = function(array $top6, int $player = 1, int $skip = 0) {
    $rows = [['player' => $player, 'zone' => 'myHand', 'cardID' => 'usa6qyq3ka']]; // Galestream Insight -> myHand-7
    // $skip: deck slots to leave alone (player 2's turn-start draw takes myDeck-0 before the activation)
    foreach ($top6 as $i => $cardID) $rows[] = ['player' => $player, 'patchMzId' => 'myDeck-' . ($i + $skip), 'setProperties' => ['CardID' => $cardID]];
    return $rows;
};
$fixtures['galestream-insight-look-six-reveal-spell-rest-bottom'] = [
    'testedCards' => ['usa6qyq3ka'],
    'deck' => $gaGalestreamDeck,
    // top six, top to bottom: Dungeon Guide, Fluffy Shopkeep, Fairy Whispers (SPELL), Dungeon Guide, Refracting Missile (SPELL), Fluffy Shopkeep
    'setup' => $gaGalestreamSetup(['em6eEh9q8y', 'px60u5n1do', 'n8wyfG9hbY', 'em6eEh9q8y', '6ffqsuo6gb', 'px60u5n1do']),
    'actions' => array_merge([mrdPlay(1, 'myHand-7')], mrdPay(1, 4), [
        mrdAns(1, 'myTempZone-2'), // reveal Fairy Whispers (the first spell, 3rd of the six) into memory
    ]),
];
$fixtures['galestream-insight-look-six-deep-spell-offered'] = [
    'testedCards' => ['usa6qyq3ka'],
    'deck' => $gaGalestreamDeck,
    // the ONLY spell is the sixth card from the top (Refracting Missile): it can only be offered if all six were looked at
    'setup' => $gaGalestreamSetup(['em6eEh9q8y', 'px60u5n1do', 'em6eEh9q8y', 'px60u5n1do', 'em6eEh9q8y', '6ffqsuo6gb']),
    'actions' => array_merge([mrdPlay(1, 'myHand-7')], mrdPay(1, 4), [
        mrdAns(1, 'myTempZone-5'), // reveal Refracting Missile (6th card) into memory
    ]),
];
$fixtures['galestream-insight-look-six-decline-bottoms-all-six'] = [
    'testedCards' => ['usa6qyq3ka'],
    'deck' => $gaGalestreamDeck,
    'setup' => $gaGalestreamSetup(['em6eEh9q8y', 'px60u5n1do', 'n8wyfG9hbY', 'em6eEh9q8y', '6ffqsuo6gb', 'px60u5n1do']),
    'actions' => array_merge([mrdPlay(1, 'myHand-7')], mrdPay(1, 4), [
        mrdPass(1), // decline revealing a spell
    ]),
];
$fixtures['galestream-insight-player-two-look-six-reveal-spell-rest-bottom'] = [
    'testedCards' => ['usa6qyq3ka'],
    'deck' => $gaGalestreamDeck,
    // PLAYER 2 seating (perspective check): the same top-six stack sits under player 2's turn-start draw (deck slots 1..6)
    'setup' => $gaGalestreamSetup(['em6eEh9q8y', 'px60u5n1do', 'n8wyfG9hbY', 'em6eEh9q8y', '6ffqsuo6gb', 'px60u5n1do'], 2, 1),
    'actions' => array_merge([mrdEnd(1), mrdPlay(2, 'myHand-7')], mrdPay(2, 4), [
        mrdAns(2, 'myTempZone-2'), // reveal Fairy Whispers into player 2's memory
    ]),
];
$fixtures['galestream-insight-look-six-no-spell-bottoms-all-six'] = [
    'testedCards' => ['usa6qyq3ka'],
    'deck' => $gaGalestreamDeck,
    'setup' => $gaGalestreamSetup(['em6eEh9q8y', 'px60u5n1do', 'em6eEh9q8y', 'px60u5n1do', 'em6eEh9q8y', 'px60u5n1do']),
    'actions' => array_merge([mrdPlay(1, 'myHand-7')], mrdPay(1, 4)),
];

// --- Shackled Theurgist (vkqzk1jik7): "On Death: Target opponent may sacrifice an ally. If they don't, return Shackled
// Theurgist to the field. It gets +2 LIFE until end of turn and becomes ephemeral." ---
// The Theurgist is killed for real by Drenching Finish (2 power vs the Theurgist's 2 life); the On Death trigger goes on the
// effect stack and the opponent of its controller is asked "Sacrifice an ally?".
$gaTheurgistDeck = <<<'DECK'
# Material
1 Spirit of Water
# Main
10 Dungeon Guide
10 Fluffy Shopkeep
DECK;
// Seating helper: $ctrl controls the Theurgist (field-1) and the OTHER player ($opp) kills it with Drenching Finish. The
// controller also has its own Dungeon Guide ally (field-2) -- the opponent must never be offered THAT ally to sacrifice.
// $oppAlly: whether the opponent (the killer) has a Dungeon Guide ally of its own (-> the "Sacrifice an ally?" prompt exists).
$gaTheurgistSetup = function(int $ctrl, bool $oppAlly = true) {
    $opp = $ctrl == 1 ? 2 : 1;
    $rows = [
        ['player' => $ctrl, 'zone' => 'myField', 'cardID' => 'vkqzk1jik7'], // Shackled Theurgist -> controller field-1
        ['player' => $ctrl, 'zone' => 'myField', 'cardID' => 'em6eEh9q8y'], // controller's own Dungeon Guide ally -> field-2 (must NOT be offered for sacrifice)
    ];
    if ($oppAlly) $rows[] = ['player' => $opp, 'zone' => 'myField', 'cardID' => 'px60u5n1do']; // opponent's Fluffy Shopkeep ally -> opponent field-1 (the only legal sacrifice)
    $rows[] = ['player' => $opp, 'zone' => 'myHand', 'cardID' => 'en3DD836cp']; // Drenching Finish -> opponent myHand-7
    return $rows;
};
// Opening actions: the killer ($opp) plays Drenching Finish for real, pays 2 reserve and attacks the Theurgist (field-1 of the other side).
$gaTheurgistKill = function(int $ctrl) {
    $opp = $ctrl == 1 ? 2 : 1;
    $lead = $opp == 1 ? [mrdEnd(1), mrdEnd(2)] : [mrdEnd(1)]; // player 1 attacks on its turn 3, player 2 on its turn 2
    return array_merge($lead, [mrdPlay($opp, 'myHand-7')], mrdPay($opp, 2), [mrdAns($opp, 'theirField-1')]);
};
foreach ([2, 1] as $gaTheurgistCtrl) {
    $gaTheurgistOpp = $gaTheurgistCtrl == 1 ? 2 : 1;
    $gaTheurgistTag = 'p' . $gaTheurgistCtrl . '-controlled';
    $fixtures["shackled-theurgist-$gaTheurgistTag-opponent-declines-sacrifice-returns-ephemeral"] = [
        'testedCards' => ['vkqzk1jik7'],
        'deck' => $gaTheurgistDeck,
        'setup' => $gaTheurgistSetup($gaTheurgistCtrl),
        'actions' => array_merge($gaTheurgistKill($gaTheurgistCtrl), [mrdAns($gaTheurgistOpp, 'NO')]),
    ];
    $fixtures["shackled-theurgist-$gaTheurgistTag-opponent-sacrifices-own-ally-stays-dead"] = [
        'testedCards' => ['vkqzk1jik7'],
        'deck' => $gaTheurgistDeck,
        'setup' => $gaTheurgistSetup($gaTheurgistCtrl),
        'actions' => array_merge($gaTheurgistKill($gaTheurgistCtrl), [
            mrdAns($gaTheurgistOpp, 'YES'),
            mrdAns($gaTheurgistOpp, 'theirField-1', ['expectFailure' => true, 'semantic' => true, 'label' => "The controller's own Dungeon Guide was never offered: the opponent can only sacrifice ITS OWN ally"]),
            mrdAns($gaTheurgistOpp, 'myField-1'), // sacrifice the opponent's own Fluffy Shopkeep
        ]),
    ];
    $fixtures["shackled-theurgist-$gaTheurgistTag-opponent-has-no-ally-returns-ephemeral"] = [
        'testedCards' => ['vkqzk1jik7'],
        'deck' => $gaTheurgistDeck,
        'setup' => $gaTheurgistSetup($gaTheurgistCtrl, false),
        'actions' => $gaTheurgistKill($gaTheurgistCtrl),
    ];
}

// --- Bygone Days (wXNDSNQ2x2): "At the beginning of your recollection phase, cascade -- 1: Recover 2. 2: Recover 1.
// 3: Each player chooses an ally they control and returns it to its owner's memory. Sacrifice CARDNAME." ---
// The phantasia is played for real; its cascade then triggers on the controller's 1st/2nd/3rd recollection phase.
$gaBygoneDeck = <<<'DECK'
# Material
1 Spirit of Water
# Main
10 Dungeon Guide
10 Fluffy Shopkeep
DECK;
// $ctrl controls Bygone Days (played for real). Setup: controller champion damaged 5; controller ally = Dungeon Guide (field-1),
// opponent allies = Fluffy Shopkeep (field-1) + Dungeon Guide (field-2).
$gaBygoneSetup = function(int $ctrl) {
    $opp = $ctrl == 1 ? 2 : 1;
    return [
        ['player' => $ctrl, 'patchMzId' => 'myField-0', 'setProperties' => ['Damage' => 5]], // controller champion damaged 5 (Recover 2 -> 3, Recover 1 -> 2)
        ['player' => $ctrl, 'zone' => 'myField', 'cardID' => 'em6eEh9q8y'], // controller Dungeon Guide -> field-1
        ['player' => $opp, 'zone' => 'myField', 'cardID' => 'px60u5n1do'], // opponent Fluffy Shopkeep -> field-1
        ['player' => $opp, 'zone' => 'myField', 'cardID' => 'em6eEh9q8y'], // opponent Dungeon Guide -> field-2
        ['player' => $ctrl, 'zone' => 'myHand', 'cardID' => 'wXNDSNQ2x2'], // Bygone Days -> controller myHand-7
    ];
};
// Actions to reach the controller's Nth recollection phase after playing the card: play + 2 reserve, then pass turns.
$gaBygoneToCascade = function(int $ctrl, int $n) {
    $rows = $ctrl == 1 ? [mrdPlay(1, 'myHand-7')] : [mrdEnd(1), mrdPlay(2, 'myHand-7')];
    $rows = array_merge($rows, mrdPay($ctrl, 2));
    for ($i = 0; $i < $n; ++$i) {
        $rows[] = mrdEnd($ctrl);
        $rows[] = mrdEnd($ctrl == 1 ? 2 : 1);
    }
    return $rows;
};
foreach ([1, 2] as $gaBygoneCtrl) {
    $gaBygoneOpp = $gaBygoneCtrl == 1 ? 2 : 1;
    $fixtures["bygone-days-p$gaBygoneCtrl-controlled-cascade-recovers-then-each-player-returns-ally"] = [
        'testedCards' => ['wXNDSNQ2x2'],
        'deck' => $gaBygoneDeck,
        'setup' => $gaBygoneSetup($gaBygoneCtrl),
        'actions' => array_merge($gaBygoneToCascade($gaBygoneCtrl, 3), [
            mrdAns($gaBygoneCtrl, 'myField-1'), // the controller returns its own Dungeon Guide to its memory
            mrdAns($gaBygoneOpp, 'myField-0', ['expectFailure' => true, 'semantic' => true, 'label' => "The opponent's champion is not an ally (and was never offered): it cannot be chosen"]),
            // the opponent returns one of ITS OWN two allies (player 1 as opponent: its 2nd ally, player 2 as opponent: its 1st)
            mrdAns($gaBygoneOpp, $gaBygoneOpp == 2 ? 'myField-2' : 'myField-1'),
        ]),
    ];
}
// Ownership: the controller controls an ally OWNED by the opponent. "Returns it to its OWNER's memory": it goes to the OPPONENT's memory.
$fixtures['bygone-days-p1-controlled-returns-opponent-owned-ally-to-owner-memory'] = [
    'testedCards' => ['wXNDSNQ2x2'],
    'deck' => $gaBygoneDeck,
    'setup' => [
        ['player' => 1, 'zone' => 'myField', 'cardID' => 'em6eEh9q8y', 'setProperties' => ['Owner' => 2]], // Dungeon Guide controlled by player 1 but OWNED by player 2 -> p1 field-1
        ['player' => 1, 'zone' => 'myHand', 'cardID' => 'wXNDSNQ2x2'], // Bygone Days -> p1 myHand-7
    ],
    'actions' => array_merge($gaBygoneToCascade(1, 3), [
        mrdAns(1, 'myField-1'), // player 1 chooses the ally it controls (owned by player 2)
    ]),
];
// Slot order: the controller's ally sits AFTER Bygone Days on the field, so sacrificing Bygone Days shifts it down a slot.
$fixtures['bygone-days-p1-controlled-ally-after-bygone-days-slot-shifts-on-sacrifice'] = [
    'testedCards' => ['wXNDSNQ2x2'],
    'deck' => $gaBygoneDeck,
    'setup' => [
        ['player' => 1, 'zone' => 'myHand', 'cardID' => 'px60u5n1do'], // Fluffy Shopkeep -> p1 myHand-7
        ['player' => 1, 'zone' => 'myHand', 'cardID' => 'wXNDSNQ2x2'], // Bygone Days -> p1 myHand-8
    ],
    'actions' => array_merge([mrdPlay(1, 'myHand-8')], mrdPay(1, 2), [mrdPlay(1, 'myHand-5')], mrdPay(1, 3),
